class ManipulandoVetores {
  public void ordenarVetor(int[] vetor) {
    Arrays.sort(vetor);
    System.out.print("Vetor ordenado: ");
    for (int num : vetor) {
      System.out.print(num + " ");
    }
    System.out.println();
  }
  public void mostrarMaiorElemento(int[] vetor) {
    int maior = vetor[vetor.length - 1];
    System.out.println("Maior elemento do vetor: " + maior);
  }
}
